def aicat_a_agencia(apps, schema_editor):
    """Each AICAT row becomes the agency of its listing (the number was always the agency's)."""
    Agencia = apps.get_model('base', 'Agencia')
    RegistroLegal = apps.get_model('base', 'RegistroLegal')
    for fila in RegistroLegal.objects.filter(tipo='aicat').select_related('inmueble'):
        if fila.numero:
            agencia, _ = Agencia.objects.get_or_create(aicat=fila.numero, defaults={'nombre': f'AICAT {fila.numero}'})
            if fila.inmueble.agencia_id is None:
                fila.inmueble.agencia = agencia
                fila.inmueble.save(update_fields=['agencia'])
        fila.delete()


def agencia_a_aicat(apps, schema_editor):
    RegistroLegal = apps.get_model('base', 'RegistroLegal')
    Inmueble = apps.get_model('base', 'Inmueble')
    for inmueble in Inmueble.objects.exclude(agencia=None).exclude(agencia__aicat='').select_related('agencia'):
        RegistroLegal.objects.get_or_create(
            inmueble=inmueble, tipo='aicat', defaults={'numero': inmueble.agencia.aicat})


